def transform(grid):
    from collections import Counter

    H = len(grid)
    if H == 0: return grid
    W = len(grid[0]) if H > 0 else 0
    if W == 0: return grid

    best_h, best_w = -1, -1
    min_diffs = float('inf')
    best_modes = {}

    # We search for a smaller period to avoid trivial identity copy (h=H, w=W).
    # h=H, w=W corresponds to reconstructing the input grid exactly.
    # Since the input grid contains noise (e.g. blocks of 0, 4, 7), reconstructing it
    # would propagate the noise. By searching for h < H and w < W, we find the
    # periodic pattern that explains the "clean" parts of the grid best.
    # Range starts at 1 to handle cases where the period might be small (e.g. h=1 if all rows were same).
    for h in range(1, H):
        for w in range(1, W):
            counts_map = {}

            # Collect values for each periodic cell (i, j)
            for r in range(H):
                for c in range(W):
                    i = r % h
                    j = c % w
                    val = grid[r][c]
                    counts_map.setdefault((i, j), []).append(val)

            modes = {}
            # Determine the most common value for each pattern cell
            for key, vals in counts_map.items():
                c = Counter(vals)
                if c:
                    modes[key] = c.most_common(1)[0][0]

            # Calculate mismatches compared to the input grid
            mismatches = 0
            for r in range(H):
                for c in range(W):
                    i, j = r % h, c % w
                    if grid[r][c] != modes[(i, j)]:
                        mismatches += 1

            # Update best if we found a better period (fewer mismatches)
            if mismatches < min_diffs:
                min_diffs = mismatches
                best_h, best_w = h, w
                best_modes = modes

    if best_h != -1:
        # Reconstruct the grid using the best pattern found
        output_grid = []
        for r in range(H):
            row = []
            for c in range(W):
                i, j = r % best_h, c % best_w
                row.append(best_modes[(i, j)])
            output_grid.append(row)
        return output_grid
    else:
        # Fallback: return original grid
        return grid
